const f = $('Décrire la cible').first().json;
const HOST_CHARS = new RegExp('^[a-z0-9.-]+$');
function pick(k, label) {
  const v = f[k] !== undefined ? f[k] : f[label];
  return v === undefined || v === null ? '' : String(v).trim();
}
function hostOf(u) {
  let s = String(u || '').trim().toLowerCase();
  if (!s) return '';
  const p = s.indexOf('://');
  if (p >= 0) s = s.slice(p + 3);
  let end = s.length;
  ['/', '?', '#'].forEach(function (c) { const i = s.indexOf(c); if (i >= 0 && i < end) end = i; });
  s = s.slice(0, end);
  const at = s.lastIndexOf('@');
  if (at >= 0) s = s.slice(at + 1);
  const colon = s.indexOf(':');
  if (colon >= 0) s = s.slice(0, colon);
  while (s.slice(-1) === '.') s = s.slice(0, -1);
  return s;
}
function domainOf(u) {
  const h = hostOf(u);
  return h.indexOf('www.') === 0 ? h.slice(4) : h;
}
const known = {};
function walk(v, depth) {
  if (depth > 6 || v === null || v === undefined) return;
  if (typeof v === 'string') {
    if (v.indexOf('http') === 0) {
      const d = domainOf(v);
      if (d && d.indexOf('.') > 0 && HOST_CHARS.test(d) && d.indexOf('notion.so') < 0 && d.indexOf('notion.site') < 0) known[d] = true;
    }
    return;
  }
  if (Array.isArray(v)) { v.forEach(function (x) { walk(x, depth + 1); }); return; }
  if (typeof v === 'object') Object.keys(v).forEach(function (k) { walk(v[k], depth + 1); });
}
let notionError = '';
let pages = [];
try { pages = $('Lire les prospects déjà dans Notion').all().map(function (i) { return i.json; }); } catch (e) { pages = []; }
if (pages[0] && pages[0].error) {
  notionError = typeof pages[0].error === 'string' ? pages[0].error : String(pages[0].error.message || 'Notion injoignable');
  pages = [];
}
pages.forEach(function (p) { walk(p, 0); });
const domains = Object.keys(known);
const count = Math.max(3, Math.min(15, parseInt(pick('count', 'Nombre de prospects'), 10) || 10));
const sector = pick('sector', "Type d'entreprise");
const zone = pick('zone', 'Zone géographique');
return [{ json: {
  sector: sector,
  zone: zone,
  size: pick('size', 'Taille visée') || 'Indifférent',
  signal: pick('signal', 'Signal recherché'),
  offer: pick('offer', 'Notre offre en une phrase'),
  count: count,
  known_domains: domains,
  exclude: domains.length ? domains.slice(0, 300).join(', ') : 'aucun',
  notion_error: notionError,
  search_label: sector + ', ' + zone
} }];

