const p = $('Préparer la recherche').first().json;
const raw = $input.first().json;
const HOST_CHARS = new RegExp('^[a-z0-9.-]+$');

function claudeText(r) {
  if (!r || !Array.isArray(r.content)) return '';
  return r.content.filter(function (b) { return b && b.type === 'text'; }).map(function (b) { return b.text || ''; }).join('');
}
function claudeError(r) {
  if (!r || typeof r !== 'object') return 'aucune réponse';
  if (typeof r.error === 'string') return r.error;
  if (r.error && r.error.message) return String(r.error.message);
  if (r.stop_reason === 'refusal') return 'refus du modèle';
  if (r.stop_reason === 'max_tokens') return 'réponse coupée';
  if (r.stop_reason === 'pause_turn') return 'recherche interrompue avant la réponse';
  return '';
}
function parseJson(t) {
  const i = t.indexOf('{'), k = t.lastIndexOf('}');
  if (i < 0 || k <= i) return null;
  try { return JSON.parse(t.slice(i, k + 1)); } catch (e) { return null; }
}
function clean(v, max) {
  const em = String.fromCharCode(8212), en = String.fromCharCode(8211);
  return String(v || '').split(' ' + em + ' ').join(', ').split(' ' + en + ' ').join(', ').split(em).join(', ').split(en).join('-').trim().slice(0, max || 500);
}
function hostOf(u) {
  let s = String(u || '').trim().toLowerCase();
  if (!s) return '';
  const q = s.indexOf('://');
  if (q >= 0) s = s.slice(q + 3);
  let end = s.length;
  ['/', '?', '#'].forEach(function (c) { const i = s.indexOf(c); if (i >= 0 && i < end) end = i; });
  s = s.slice(0, end);
  const at = s.lastIndexOf('@');
  if (at >= 0) s = s.slice(at + 1);
  const colon = s.indexOf(':');
  if (colon >= 0) s = s.slice(0, colon);
  while (s.slice(-1) === '.') s = s.slice(0, -1);
  return s;
}
function domainOf(u) {
  const h = hostOf(u);
  return h.indexOf('www.') === 0 ? h.slice(4) : h;
}
function isPublicHost(h) {
  if (!h || h.indexOf('.') < 0 || !HOST_CHARS.test(h)) return false;
  if (h === 'localhost' || h.slice(-6) === '.local' || h.slice(-9) === '.internal' || h.slice(-4) === '.lan' || h.slice(-5) === '.home') return false;
  const parts = h.split('.');
  if (parts.some(function (x) { return x === ''; })) return false;
  if (parts.every(function (x) { return !isNaN(Number(x)); })) return false;
  return true;
}
function safeUrl(u) {
  const d = domainOf(u);
  if (!d || !isPublicHost(d)) return '';
  const s = String(u).trim();
  return s.indexOf('http') === 0 ? s.slice(0, 500) : 'https://' + s.slice(0, 490);
}
const BLOCKED = ['linkedin.com', 'facebook.com', 'instagram.com', 'x.com', 'twitter.com', 'youtube.com', 'google.com', 'wikipedia.org', 'pagesjaunes.fr', 'societe.com', 'pappers.fr', 'infogreffe.fr', 'verif.com', 'manageo.fr', 'kompass.com', 'indeed.com', 'indeed.fr', 'welcometothejungle.com', 'hellowork.com', 'data.gouv.fr', 'mappy.com', 'tripadvisor.fr', 'yelp.fr'];
function blocked(d) {
  return BLOCKED.some(function (b) { return d === b || d.slice(-(b.length + 1)) === '.' + b; });
}

const known = {};
(p.known_domains || []).forEach(function (d) { known[d] = true; });
const text = claudeText(raw);
const data = text ? parseJson(text) : null;
const today = DateTime.now().setZone('Europe/Paris').toISODate();
const list = data && Array.isArray(data.prospects) ? data.prospects : [];
const out = [];
const seen = {};
const skipped = [];

list.forEach(function (x) {
  const name = clean(x && x.entreprise, 150);
  const d = domainOf(x && x.site);
  if (!d || !isPublicHost(d)) { skipped.push((name || 'sans nom') + ' : pas de site officiel'); return; }
  if (blocked(d)) { skipped.push((name || d) + ' : annuaire ou réseau social'); return; }
  if (known[d]) { skipped.push((name || d) + ' : déjà dans Notion'); return; }
  if (seen[d]) return;
  seen[d] = true;
  const score = Math.max(1, Math.min(5, Math.round(Number(x.pertinence)) || 3));
  out.push({ json: {
    kind: 'prospect',
    entreprise: name || d,
    site: 'https://' + (x.site && String(x.site).toLowerCase().indexOf('://www.') >= 0 ? 'www.' : '') + d,
    domain: d,
    ville: clean(x.ville, 120),
    secteur: clean(x.secteur, 200),
    taille: clean(x.taille_estimee, 80),
    signal: clean(x.signal, 600),
    source_signal: safeUrl(x.source_signal),
    decideur: clean(x.decideur, 150),
    source_decideur: safeUrl(x.source_decideur),
    pertinence: score,
    pourquoi: clean(x.pourquoi, 600),
    angle: clean(x.angle, 400),
    recherche: p.search_label,
    ecartes: skipped.slice(),
    date: today
  } });
});

if (!out.length) {
  const reason = !data
    ? 'Recherche impossible : ' + (claudeError(raw) || 'réponse illisible') + '.'
    : 'Aucun nouveau prospect retenu' + (skipped.length ? ' (' + skipped.length + ' écartés : ' + skipped.slice(0, 5).join(' ; ') + ').' : '.');
  out.push({ json: {
    kind: 'erreur', entreprise: 'Recherche sans résultat : ' + p.search_label, site: '', domain: '', ville: '', secteur: '', taille: '', signal: '',
    source_signal: '', decideur: '', source_decideur: '', pertinence: 0,
    pourquoi: reason + (p.notion_error ? ' Lecture de Notion : ' + p.notion_error : ''),
    angle: '', recherche: p.search_label, date: today
  } });
}
return out.slice(0, p.count);

const items = $('Lister les prospects').all();
const checks = $input.all();
function errText(e) { return typeof e === 'string' ? e : String((e && e.message) || 'pas de réponse'); }
return items.map(function (it, i) {
  const x = Object.assign({}, it.json);
  const c = (checks[i] || {}).json || {};
  if (x.kind !== 'prospect') {
    x.statut = 'Erreur';
    x.details = x.pourquoi;
    return { json: x };
  }
  if (c.error || !c.statusCode) {
    x.statut = 'Site à vérifier';
    x.site_check = 'Site injoignable : ' + errText(c.error);
  } else {
    const body = String(c.body || '');
    const m = body.match(new RegExp('<title[^>]*>([^<]*)</title>', 'i'));
    const rawTitle = m ? m[1].trim().slice(0, 120) : '';
    const title = rawTitle.indexOf(String.fromCharCode(65533)) >= 0 ? '' : rawTitle;
    const hay = (title + ' ' + body.slice(0, 30000)).toLowerCase();
    const words = String(x.entreprise).toLowerCase().split(' ').filter(function (w) { return w.length > 3; });
    const match = !words.length || words.some(function (w) { return hay.indexOf(w) >= 0; });
    x.statut = match ? 'À contacter' : 'Site à vérifier';
    x.site_check = 'Site vérifié (HTTP ' + c.statusCode + ')' + (title ? ', titre : ' + title : '') + (match ? '' : ". Le nom de l'entreprise n'apparaît pas sur la page d'accueil.");
  }
  x.details = [x.site_check, x.taille ? 'Taille estimée : ' + x.taille : '', x.source_decideur ? 'Source du décideur : ' + x.source_decideur : ''].filter(function (s) { return s; }).join(' | ');
  return { json: x };
});
